using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Extensions.AI;
using OpenAI;

// --- Tool definitions ---

/// <summary>Tools available to the research agent.</summary>
static class ResearchTools
{
    private static readonly List<string> _notes = [];
    private static readonly HttpClient _http = new();

    [Description("Search the web for information on a given query. Returns a list of result snippets.")]
    public static async Task<string> SearchWeb(string query)
    {
        // Uses DuckDuckGo Instant Answer API as a free search source
        var encoded = Uri.EscapeDataString(query);
        var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1";

        try
        {
            var response = await _http.GetFromJsonAsync<JsonElement>(url);

            var results = new List<string>();

            // Abstract text (main answer)
            var abstractText = response.GetProperty("AbstractText").GetString();
            if (!string.IsNullOrWhiteSpace(abstractText))
                results.Add($"[Summary] {abstractText}");

            // Related topics
            if (response.TryGetProperty("RelatedTopics", out var topics))
            {
                foreach (var topic in topics.EnumerateArray().Take(5))
                {
                    if (topic.TryGetProperty("Text", out var text))
                        results.Add($"[Related] {text.GetString()}");
                }
            }

            return results.Count > 0
                ? string.Join("\n\n", results)
                : $"No detailed results found for '{query}'. Try rephrasing or breaking the query into sub-topics.";
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}";
        }
    }

    [Description("Save a research note. Use this to record key findings during research.")]
    public static string SaveNote(string note)
    {
        _notes.Add(note);
        return $"Note saved (total notes: {_notes.Count}).";
    }

    [Description("Retrieve all saved research notes.")]
    public static string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        return string.Join("\n---\n", _notes.Select((n, i) => $"Note {i + 1}: {n}"));
    }
}

// --- Main program ---

Console.WriteLine("═══════════════════════════════════════");
Console.WriteLine("       AI Research Agent (.NET 10)      ");
Console.WriteLine("═══════════════════════════════════════");
Console.WriteLine();

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY");
if (string.IsNullOrEmpty(apiKey))
{
    Console.ForegroundColor = ConsoleColor.Red;
    Console.WriteLine("Error: Set the OPENAI_API_KEY environment variable.");
    Console.ResetColor();
    return;
}

var openAiClient = new OpenAIClient(apiKey);
IChatClient chatClient = openAiClient.GetChatClient("gpt-4o-mini").AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

var chatOptions = new ChatOptions
{
    Tools =
    [
        AIFunctionFactory.Create(ResearchTools.SearchWeb),
        AIFunctionFactory.Create(ResearchTools.SaveNote),
        AIFunctionFactory.Create(ResearchTools.GetNotes),
    ]
};

var systemPrompt = """
    You are a research agent. Your job is to research a topic thoroughly by:
    1. Breaking the topic into sub-questions
    2. Using the SearchWeb tool to find information
    3. Using the SaveNote tool to record important findings
    4. After gathering enough information, using GetNotes to review your findings
    5. Providing a comprehensive summary with key points

    Always search multiple angles of a topic and save notes as you go.
    When you have enough information, synthesize everything into a clear summary.
    """;

var messages = new List<ChatMessage>
{
    new(ChatRole.System, systemPrompt)
};

Console.Write("Enter a research topic: ");
var topic = Console.ReadLine();

if (string.IsNullOrWhiteSpace(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

messages.Add(new(ChatRole.User, $"Research the following topic and provide a comprehensive summary: {topic}"));

Console.WriteLine();
Console.WriteLine($"Researching: {topic}");
Console.WriteLine("───────────────────────────────────────");

var response = await chatClient.GetResponseAsync(messages, chatOptions);

Console.WriteLine();
Console.WriteLine("═══════════════════════════════════════");
Console.WriteLine("           Research Summary            ");
Console.WriteLine("═══════════════════════════════════════");
Console.WriteLine();
Console.WriteLine(response.Text);
Console.WriteLine();

